                     end if
                     ! (ad)(kl)
                     idx = pspace_find(block_key, nblock, pspace_key((/b,c,d,i,j,l/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,1); m = t4_excits_buff(jdet,5);
                        ! compute < ijklabcd | h2b(ovvo) | mi~j~l~eb~c~d~ >
                        !hmatel = h2b_ovvo(m,a,e,k)
                        hmatel = h2b_ovvo(m,e,a,k)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (bd)(kl)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,c,d,i,j,l/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,1); m = t4_excits_buff(jdet,5);
                        ! compute < ijklabcd | h2b(ovvo) | mi~j~l~ea~c~d~ >
                        !hmatel = -h2b_ovvo(m,b,e,k)
                        hmatel = -h2b_ovvo(m,e,b,k)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (cd)(kl)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,d,i,j,l/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,1); m = t4_excits_buff(jdet,5);
                        ! compute < ijklabcd | h2b(ovvo) | mi~j~l~ea~b~d~ >
                        !hmatel = h2b_ovvo(m,c,e,k)
                        hmatel = h2b_ovvo(m,e,c,k)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  ! deallocate sorting arrays
                  deallocate(block_key,block_off)
                  ! deallocate t4 buffer arrays
                  deallocate(t4_amps_buff,t4_excits_buff)

                  call release_sort_workspace()
              end subroutine t4e_p_lin

end module ccsdtq_p_t4e_p_lin
